globalThis.KENGURU_GRADES_5_6 = [{"year":2014,"id":"2014-5-6","grades":[5,6],"label":"5–6 классы","tasksUrl":"assets/kenguru/kenguru_2014_class_5-6.pdf","answersUrl":"assets/kenguru/kenguru_2014_answers.pdf","solutionUrl":null,"cards":[[753,83,null],[754,121,null],[749,61,null],[753,148,null],[753,123,null],[731,89,null],[753,82,null],[752,164,null],[752,113,null],[752,85,null],[752,147,null],[753,130,null],[754,95,null],[753,85,null],[753,169,null],[750,116,null],[753,149,null],[753,84,null],[754,190,null],[754,103,null],[754,103,null],[753,104,null],[754,126,null],[754,131,null],[754,183,null],[754,88,null],[740,157,null],[754,178,null],[753,85,null],[754,218,null]]}];
globalThis.KENGURU_GRADE_CONDITIONS = {"2014":{"1":{"question":"В 2014 году конкурс «Кенгуру» проводится 20 марта. Какой по счету это день с начала года?","choices":["77","78","79","80","81"]},"2":{"question":"Арина разбирает мамины бусы. Она хочет снять 5 темных бусин. Какое наименьшее количество белых бусин ей потребуется снять для этого?","choices":["2","3","4","5","6"],"image":"assets/grade-conditions/2014/task-02.webp","imageWidth":696,"imageHeight":52},"3":{"question":"Какое слово написано верно?","choices":["перимитр","пириметр","периметор","приметр","периметр"]},"4":{"question":"Два кольца, белое и темное, зацеплены друг за друга так, как изображено на рисунке справа. Как эти кольца выглядят с другой стороны?","image":"assets/grade-conditions/2014/task-04.webp","imageWidth":962,"imageHeight":197},"5":{"question":"Торт весит 900 г. Павел разрезал его на несколько частей так, что самая большая часть весит столько же, сколько весят вместе все остальные части. Сколько весит бóльшая часть?","choices":["100 г","200 г","300 г","450 г","600 г"]},"6":{"question":"В примере справа три цифры заменили звездочками. Какова сумма этих цифр?","choices":["0","9","10","11","19"],"image":"assets/grade-conditions/2014/task-06.svg","imageWidth":141,"imageHeight":220},"7":{"question":"Вася выписал на доске все целые числа от 1 до 100, а Веня вычел каждое из них из числа 133 и выписал результаты. Сколько чисел написано дважды?","choices":["64","65","66","67","68"]},"8":{"question":"Электронные часы Бена идут правильно, но горизонтальные линии самой правой цифры не загораются. Полминуты назад часы показывали то, что изображено на рисунке 1. Сейчас они показывают то, что изображено на рисунке 2. Сколько сейчас времени?","choices":["12:40","12:42","12:44","12:47","12:49"],"image":"assets/grade-conditions/2014/task-08.webp","imageWidth":200,"imageHeight":217},"9":{"question":"Какой квадратик надо добавить, чтобы в получившемся квадрате была закрашена ровно половина площади?","choices":["Белый квадрат","Закрашенный квадрат","Закрашены верхний и нижний треугольники","Закрашена нижняя правая половина","это невозможно"],"image":"assets/grade-conditions/2014/task-09.svg","imageWidth":220,"imageHeight":217,"choiceImages":["assets/grade-conditions/2014/choice-09-1.svg","assets/grade-conditions/2014/choice-09-2.svg","assets/grade-conditions/2014/choice-09-3.svg","assets/grade-conditions/2014/choice-09-4.svg",null]},"10":{"question":"Произведение цифр трехзначного числа равно 135. Какова сумма цифр этого числа?","choices":["14","15","16","17","18"]},"11":{"question":"Выбрав четыре из пяти деталей А–Д, можно составить квадрат. Какая деталь не будет использована?","image":"assets/grade-conditions/2014/task-11.webp","imageWidth":940,"imageHeight":129},"12":{"question":"Доктор Пилюлькин прописал семи коротышкам по одной пилюле каждый день, а девяти другим коротышкам — по одной пилюле через день. Сегодня доктор Пилюлькин выдал этим коротышкам 13 пилюль. Сколько пилюль он выдаст им завтра?","choices":["7","8","9","10","13"]},"13":{"question":"На рисунке AF = 35, AC = 12, BD = 11, CE = 12, DF = 16. Чему равна длина отрезка BE?","choices":["17","16","15","14","13"],"image":"assets/grade-conditions/2014/task-13.webp","imageWidth":352,"imageHeight":52},"14":{"question":"Какое наибольшее число можно получить, если из разности двух трехзначных чисел вычесть сумму трех различных двузначных чисел?","choices":["865","866","867","869","870"]},"15":{"question":"Саша принесла с пляжа ракушки. Когда она попыталась разделить их на 3 равные кучки, осталось 2 ракушки. Тогда она попыталась поделить все эти ракушки на 5 равных кучек, но опять осталось 2 ракушки. Какое наименьшее количество ракушек надо добавить, чтобы все ракушки можно было разложить поровну и на 3 кучки, и на 5 кучек?","choices":["2","3","8","13","14"]},"16":{"question":"Какой кубик получится из данной развёртки?","choices":["Слева стрелка вверх, справа вниз","Слева стрелка влево, справа вниз","Обе стрелки вверх","Слева стрелка вниз, справа вверх","Слева стрелка влево, справа вправо"],"image":"assets/grade-conditions/2014/task-16.svg","imageWidth":220,"imageHeight":169,"choiceImages":["assets/grade-conditions/2014/choice-16-1.webp","assets/grade-conditions/2014/choice-16-2.webp","assets/grade-conditions/2014/choice-16-3.webp","assets/grade-conditions/2014/choice-16-4.webp","assets/grade-conditions/2014/choice-16-5.webp"]},"17":{"question":"В 12:00 Петя пошел в соседнюю деревню. Вместе с ним в том же направлении выбежал пес Шарик. Добежав до соседней деревни в 14:30, Шарик повернул обратно и встретил Петю в 15:30. Во сколько раз скорость Шарика больше скорости Пети?","image":"assets/grade-conditions/2014/task-17.webp","imageWidth":862,"imageHeight":68},"18":{"question":"Число 111…111 (2014 единиц) умножили на 101. Какова сумма цифр произведения?","choices":["2014","2016","4026","4027","4028"]},"19":{"question":"После того, как в 3 часа ночи прозвенел Васин будильник, и Вася стукнул по нему кулаком, часовая стрелка будильника стала двигаться в 12 раз быстрее, чем надо. Что покажет будильник в 03:55?","image":"assets/grade-conditions/2014/task-19.webp","imageWidth":959,"imageHeight":155},"20":{"question":"На доске написаны целые числа от 1 до 10. Петя хочет стереть несколько из них так, чтобы произведение оставшихся не делилось на 6. Какое наименьшее количество чисел ему придется стереть?","choices":["5","4","3","2","1"]},"21":{"question":"Через два часа до сегодняшней полуночи останется втрое больше времени, чем 6 часов назад оставалось до полудня. Через сколько часов наступит полночь?","choices":["2","4","6","8","10"]},"22":{"question":"Куб 3×3×3 сделан из 27 маленьких кубиков. Какое наименьшее количество кубиков нужно вынуть, чтобы вид спереди, сверху и справа был таким, как на рисунке?","choices":["4","5","6","7","9"],"image":"assets/grade-conditions/2014/task-22.svg","imageWidth":220,"imageHeight":213},"23":{"question":"Кролик Эдуард в день съедает либо 9 морковок, либо 2 кочана капусты, либо 1 кочан капусты и 4 морковки, но в некоторые дни он ест только траву. За 10 дней Эдуард съел 30 морковок и 9 кочанов капусты. Сколько из этих дней он питался только травой?","choices":["1","2","3","4","5"]},"24":{"question":"В Волшебной стране каждому дождливому дню обязательно предшествуют три солнечных дня, а через неделю после каждого солнечного дня снова наступает солнечный день. На какое наибольшее число дней вперед можно предсказать погоду в дождливый день?","choices":["2","3","4","6","8"]},"25":{"question":"Сандра бегает в два раза быстрее, чем Бренда, а Бренда — в два раза быстрее, чем Николь. Девочки одновременно стартовали из одной точки кольцевой дорожки: Сандра побежала в одну сторону, а Бренда и Николь — в другую. Сначала Сандра встретила Бренду, а через 200 метров — Николь. Чему равна длина дорожки?","choices":["800 м","1000 м","1500 м","2000 м","невозможно определить"]},"26":{"question":"Пусть N — наименьшее натуральное число, остатки от деления которого на 2, 3, 4, 5 и 6 различны. Какой остаток оно дает при делении на 5?","choices":["0","1","2","3","4"]},"27":{"question":"Числа 1, …, 9 вписали в 9 клеток и выполнили действия, указанные в каждой строчке и каждом столбце. Результаты действий записали в кружках (см. рисунок). Какое число написано в клетке, отмеченной звездочкой?","choices":["9","8","7","6","5"],"image":"assets/grade-conditions/2014/task-27.webp","imageWidth":225,"imageHeight":206},"28":{"question":"На острове живут 25 человек: рыцари, которые всегда говорят правду, лжецы, которые всегда лгут, и хитрецы, каждый из которых через раз отвечает на вопросы то правду, то ложь. Каждому жителю острова было задано подряд три вопроса: «Вы рыцарь?», «Вы хитрец?», «Вы лжец?». Ответ «Да» на первый вопрос дали 17 человек, на второй — 12, на третий — 8. Сколько хитрецов на острове?","choices":["4","5","8","16","невозможно определить"]},"29":{"question":"На какое из чисел А–Д могут различаться суммы цифр двух последовательных целых чисел?","choices":["2011","2012","2013","2014","2015"]},"30":{"question":"На столе стоит 30 тарелок, на каждой из которых лежит не более 30 булочек. Время от времени в окно влетает Карлсон, выбирает несколько тарелок и съедает одинаковое количество булочек с каждой из них. За какое наименьшее число визитов Карлсон наверняка сможет съесть все булочки?","choices":["4","5","6","15","30"]}}};
globalThis.KENGURU_GRADE_SOLUTION_STEPS = {"2014":{"1":{"answer":2,"steps":[{"text":"2014 год не високосный, поэтому до марта прошло 31 + 28 = 59 дней."},{"text":"Прибавляем 20 дней марта. Двадцатое марта — 79-й день года."}]},"2":{"answer":1,"steps":[{"text":"Можно снимать бусины с обоих концов. Если с левого конца взять 0, 1, 2, 3, 4 или 5 тёмных, придётся снять соответственно 0, 0, 1, 4, 4 или 4 белых."},{"text":"Тогда с правого конца надо взять соответственно 5, 4, 3, 2, 1 или 0 тёмных. Для этого справа снимаются 5, 4, 2, 2, 0 или 0 белых."},{"text":"Наименьшая общая сумма — 1 + 2 = 3 белые бусины при двух тёмных слева и трёх справа."}]},"3":{"answer":4,"steps":[{"text":"Слово, обозначающее сумму длин сторон многоугольника, пишется «периметр»."},{"text":"Проверим его по слогам: «пе-ри-метр». Только в варианте Д есть все эти буквы в нужном порядке."}]},"4":{"answer":0,"steps":[{"text":"Если перейти за кольца, левое и правое места поменяются: тёмное кольцо окажется слева, белое справа."},{"text":"В каждом месте, где одно кольцо закрывает часть другого, теперь сверху будет видно то, которое раньше было сзади. При таком обмене перекрытия получаем рисунок А."}]},"5":{"answer":3,"steps":[{"text":"Большая часть и все остальные части вместе составляют весь торт. По условию обе группы имеют один и тот же вес."},{"text":"Поэтому большая часть весит 900 : 2 = 450 г."}]},"6":{"answer":1,"steps":[{"text":"В разряде единиц складываются 3 + 4 + 5 = 12. Пишем 2 и переносим 1 в десятки."},{"text":"В сотнях три единицы, а в результате стоит 4. Значит, из десятков перенесли ещё 1, а в самом разряде десятков записан 0."},{"text":"Следовательно, сумма трёх неизвестных цифр десятков плюс перенос 1 равна 10. Искомая сумма равна 9."}]},"7":{"answer":4,"steps":[{"text":"У Васи получились числа от 1 до 100. Результаты Вени идут от 133 − 100 = 33 до 133 − 1 = 132."},{"text":"Дважды записаны числа, которые есть в обоих списках: от 33 до 100. Их 100 − 33 + 1 = 68."}]},"8":{"answer":2,"steps":[{"text":"Полминуты назад в последней цифре горели только два правых вертикальных сегмента. Так выглядят 1, 3 и 7, если убрать горизонтальные сегменты."},{"text":"Сейчас добавился верхний левый вертикальный сегмент, так выглядят 4 и 9. Показание успело увеличиться на одну минуту, поэтому проверяем переходы 1→2, 3→4 и 7→8."},{"text":"Только 3→4 даёт второй рисунок. Сейчас 12:44."}]},"9":{"answer":4,"steps":[{"text":"На рисунке шесть клеток закрашены ровно наполовину, ещё две белые. Значит, закрашенная площадь равна трём целым клеткам."},{"text":"В квадрате 3 × 3 половина площади — 4,5 клетки. Один добавленный квадратик даёт не больше одной закрашенной клетки, всего не больше четырёх."},{"text":"Получить половину невозможно."}]},"10":{"answer":3,"steps":[{"text":"В произведении 135 = 5 · 27 есть множитель 5, который среди ненулевых цифр может дать только цифра 5."},{"text":"Две другие цифры перемножаются в 27. Из однозначных множителей подходят 3 и 9."},{"text":"Сумма цифр равна 5 + 3 + 9 = 17."}]},"11":{"answer":0,"steps":[{"text":"Для каждой выпуклой внутренней стороны нужна вогнутая. У деталей А, Б, В, Г, Д соответственно пары чисел выпуклых и вогнутых сторон (1, 1), (0, 2), (2, 0), (1, 0) и (0, 1)."},{"text":"У всех пяти деталей вместе поровну выпуклых и вогнутых сторон. Поэтому убрать можно только деталь А, у которой их тоже поровну."},{"text":"Квадрат собирается из Г и Д в верхнем ряду, Б и В в нижнем. У Б две вогнутые стороны направлены к выступам Г и В. Другой выступ В входит в выемку Д, а Г и Д сходятся прямыми сторонами."}]},"12":{"answer":3,"steps":[{"text":"Из сегодняшних 13 пилюль 7 получили те, кто принимает их ежедневно. Значит, сегодня пилюли получили 13 − 7 = 6 из девяти коротышек, принимающих их через день."},{"text":"Завтра пилюли получат остальные 9 − 6 = 3 из этой группы и все семеро из ежедневной. Всего 10 пилюль."}]},"13":{"answer":1,"steps":[{"text":"Отсчитаем расстояния от A. Точка C имеет отметку 12, а D — 35 − 16 = 19."},{"text":"Тогда отметка B равна 19 − 11 = 8, а отметка E равна 12 + 12 = 24. Длина BE равна 24 − 8 = 16."}]},"14":{"answer":1,"steps":[{"text":"Максимальная разность трёхзначных чисел равна 999 − 100 = 899."},{"text":"Минимальная сумма трёх различных двузначных чисел равна 10 + 11 + 12 = 33. При этих одновременно возможных выборах ответ равен 899 − 33 = 866."}]},"15":{"answer":3,"steps":[{"text":"Если отложить две ракушки, остальные делятся и на 3, и на 5. Их число кратно 15."},{"text":"Исходному количеству до ближайшего большего кратного 15 не хватает 15 − 2 = 13 ракушек. Столько надо добавить."}]},"16":{"answer":0,"steps":[{"text":"Обозначим клетку справа от левой стрелки за основание. При сгибании левая стрелка окажется на левой стенке куба и будет направлена от основания к верхней грани."},{"text":"От основания идём по развёртке вниз, вправо, вниз и вправо. Первая клетка пути становится передней стенкой, вторая — правой, третья — верхней, последняя со стрелкой — задней. Эта стрелка направлена от верхней грани к основанию."},{"text":"Поворачиваем куб верхней гранью кверху и смотрим на угол левой и задней стенок. Стрелка слева направлена вверх, справа вниз, как в А."}]},"17":{"answer":4,"steps":[{"text":"До деревни Шарик бежал 2,5 часа, затем один час обратно. Значит, до места встречи он успел удалиться от исходной точки на расстояние, которое пробегает за 2,5 − 1 = 1,5 часа."},{"text":"Петя прошёл это же расстояние с 12:00 до 15:30, за 3,5 часа. Отношение скоростей равно 3,5 : 1,5 = 7/3."}]},"18":{"answer":4,"steps":[{"text":"Умножить на 101 — значит сложить исходное число и то же число, сдвинутое на два разряда влево."},{"text":"На каждом из 2014 + 2014 мест было по единице до сложения. Переносов нет, потому что в одном разряде складываются не больше двух единиц."},{"text":"Поэтому сумма цифр произведения равна 4028."}]},"19":{"answer":2,"steps":[{"text":"С 03:00 до 03:55 прошло 55 минут. Минутная стрелка прошла 55 делений и показывает на 11."},{"text":"Ускоренная часовая стрелка теперь движется с той же угловой скоростью, что и минутная. Она тоже прошла 55 делений: от 3 на целый оборот без пяти делений, до 2."},{"text":"Минута на 11 и час на 2 изображены в варианте В."}]},"20":{"answer":2,"steps":[{"text":"Чтобы произведение не делилось на 6, в нём должен отсутствовать хотя бы один из множителей 2 или 3."},{"text":"Для отсутствия 2 надо стереть все пять чётных чисел. Для отсутствия 3 достаточно и необходимо стереть 3, 6 и 9."},{"text":"Меньший вариант требует стереть три числа."}]},"21":{"answer":3,"steps":[{"text":"Пусть до полуночи осталось t часов. Через два часа останется t − 2."},{"text":"Шесть часов назад до полуночи было t + 6, а до полудня на 12 часов меньше, то есть t − 6."},{"text":"Получаем t − 2 = 3(t − 6), откуда 2t = 16 и t = 8."}]},"22":{"answer":3,"steps":[{"text":"Пустая клетка вида означает, что надо вынуть все три кубика в соответствующей линии. Вид спереди требует убрать верхнюю линию от передней до задней стороны через средний столбец."},{"text":"На виде справа убирается верхняя линия по ширине в среднем ряду глубины. Она пересекает первую в одном кубике. На виде сверху убирается вертикальная линия в середине дальнего ряда. Она пересекает первую в одном кубике, а вторую не пересекает."},{"text":"Принудительно убираются 3 + 3 + 3 − 2 = 7 разных кубиков. В каждой другой линии обзора хотя бы один кубик остаётся, значит, этого достаточно."}]},"23":{"answer":1,"steps":[{"text":"Пусть a дней кролик ел по 9 морковок, а c дней — по 4. Из 9a + 4c = 30 следует, что a даёт остаток 2 при делении на 4. Так как a не больше 3, получаем a = 2 и c = 3."},{"text":"За три смешанных дня он съел три кочана, осталось 9 − 3 = 6 кочанов. Это ещё три дня по два кочана."},{"text":"На морковь и капусту ушло 2 + 3 + 3 = 8 дней. Два дня кролик ел только траву."}]},"24":{"answer":3,"steps":[{"text":"Пусть сегодня дождливый день. В следующие три дня дождя быть не может, иначе среди трёх предыдущих дней оказался бы сегодняшний несолнечный день."},{"text":"Дни за три, два и один день до сегодняшнего солнечные. Через неделю после них снова солнце, то есть солнечными будут и четвёртый, пятый и шестой дни после сегодняшнего."},{"text":"Седьмой день предсказать нельзя. Условия выполняются как при единственном дожде сегодня, так и при дожде каждые семь дней и солнце во все остальные дни."}]},"25":{"answer":2,"steps":[{"text":"Примем скорости Николь, Бренды и Сандры за 1, 2 и 4 части. При первой встрече с Брендой Сандра пробегает 4/(4 + 2) = 2/3 круга, потому что вместе они проходят одну длину дорожки."},{"text":"При первой встрече с Николь Сандра пробегает 4/(4 + 1) = 4/5 круга. Разница 4/5 − 2/3 = 2/15 круга составляет 200 м."},{"text":"Длина дорожки равна 200 · 15 : 2 = 1500 м."}]},"26":{"answer":0,"steps":[{"text":"Остатки при делении на 2, 4 и 6 имеют одну чётность. Для чётного N все три различны только при остатках 0, 2, 4 соответственно. Тогда N даёт остаток 10 при делении на 12, а при делении на 3 остаток 1."},{"text":"Из чётных кандидатов меньше 35 подходят этим условиям только 10, 22 и 34. Их остатки при делении на 5 равны 0, 2, 4, но все три остатка уже заняты."},{"text":"Для нечётного N остатки при делении на 2, 4, 6 равны 1, 3, 5. Тогда N даёт остаток 11 при делении на 12, а при делении на 3 остаток 2. Первые кандидаты 11 и 23 дают при делении на 5 уже занятые 1 и 3."},{"text":"Следующий кандидат 35 даёт при делении на 5 остаток 0, отличный от 1, 2, 3 и 5. Он наименьший."}]},"27":{"answer":2,"steps":[{"text":"В нижней строке из одного числа вычитаются два разных положительных и получается 6. Уменьшаемое не больше 9, значит, это 9, а вычитаемые — 1 и 2."},{"text":"В правом столбце сумма 8. Если внизу там 2, двум другим числам пришлось бы дать сумму 6, но обе цифры 1 и 2 уже заняты, поэтому самая маленькая сумма 3 + 4 = 7. Значит, внизу справа 1, внизу посередине 2, а сверху и в середине справа стоят 3 и 4."},{"text":"Левый столбец даёт сумму двух верхних чисел 15, это 7 и 8. Для среднего столбца остались цифры 5 и 6. Число сверху на единицу больше среднего, значит, сверху 6, в середине 5."},{"text":"В средней строке к левому числу надо прибавить правое, чтобы получить 7 + 5 = 12. Подходят 8 и 4. Тогда сверху слева, у звёздочки, остаётся 7."}]},"28":{"answer":3,"steps":[{"text":"Рыцарь отвечает «да, нет, нет», а лжец — «да, да, нет». Хитрец, начавший с правды, отвечает трижды «нет», а начавший со лжи — трижды «да»."},{"text":"На последний вопрос «да» ответили 8 хитрецов, начавших со лжи. На второй вопрос кроме них «да» сказали лжецы, их 12 − 8 = 4."},{"text":"На первый вопрос «да» сказали те же восемь хитрецов, четыре лжеца и рыцари. Рыцарей 17 − 8 − 4 = 5. Остальные 25 − 5 − 4 = 16 жителей — хитрецы."}]},"29":{"answer":4,"steps":[{"text":"Сумма цифр отрицательного числа считается без знака. Любая пара соседних целых чисел после удаления знаков даёт пару соседних неотрицательных, возможно, в обратном порядке."},{"text":"При прибавлении единицы все конечные девятки превращаются в нули, а предыдущая цифра увеличивается на 1. Если девяток k, изменение суммы равно 1 − 9k."},{"text":"Из больших положительных разностей подходят только числа на 1 меньше кратного 9. Из вариантов это 2015, потому что 2015 + 1 = 2016 = 9 · 224."},{"text":"Например, у числа из 224 девяток сумма цифр 2016, а у следующего числа сумма 1. Разность равна 2015."}]},"30":{"answer":1,"steps":[{"text":"Пронумеруем визиты количествами 1, 2, 4, 8 и 16 булочек. Любое число от 0 до 30 — сумма некоторых из них. Для каждой тарелки выбираем ровно те визиты, которые соответствуют её сумме, и за пять визитов все тарелки пусты."},{"text":"Четырёх визитов не всегда хватает. Если на тарелках лежат разные количества от 1 до 30, каждое из этих количеств должно получаться как непустая сумма из четырёх величин, съедаемых за визиты."},{"text":"У четырёх величин всего 2⁴ − 1 = 15 непустых наборов, меньше 30. Значит, гарантию дают не менее пяти визитов."}]}}};
globalThis.KENGURU_GRADE_KEYS = {"2014":[["79","В"],["3","Б"],["периметр","Д"],["Слева серое кольцо, справа белое. Они зацеплены друг за друга. В верхней точке пересечения серое проходит перед белым, а в нижней белое проходит перед серым.","А","assets/grade-key-figures/2014-04.svg",47,34],["450 г","Г"],["9","Б"],["68","Д"],["12:44","В"],["это невозможно","Д"],["17","Г"],["Серая фигура. Левый край прямой вертикальный, нижний прямой горизонтальный. Верхний край выгнут наружу, правый вогнут внутрь.","А","assets/grade-key-figures/2014-11.svg",42,47],["10","Г"],["16","Б"],["866","Б"],["13","Г"],["Куб со стрелками. На левой видимой грани стрелка направлена вверх, на правой — вниз. Верхняя грань без стрелки.","А","assets/grade-key-figures/2014-16.svg",35,37],["7/3","Д"],["4028","Д"],["На циферблате отмечены 12, 3, 6 и 9. Длинная стрелка направлена примерно к 11, короткая примерно к 2.","В","assets/grade-key-figures/2014-19.svg",53,53],["3","В"],["8","Г"],["7","Г"],["2","Б"],["6","Г"],["1500 м","В"],["0","А"],["7","В"],["16","Г"],["2015","Д"],["5","Б"]]};
globalThis.KENGURU_GRADE_TITLES = {"2014":["Какой по счёту день","Мамины бусы","Правописание термина","Кольца с другой стороны","Самый большой кусок торта","Цифры под звёздочками","Повторы на доске","Часы с погасшими линиями","Закрашенная половина квадрата","Произведение цифр равно 135","Лишняя деталь","Пилюли для коротышек","Длина отрезка BE","Из разности вычитаем сумму","Ракушки по кучкам","Кубик из развёртки","Петя и пёс Шарик","Число из 2014 единиц","Будильник с быстрой стрелкой","Стираем числа с доски","Между полуднем и полуночью","Куб с трёх сторон","Меню кролика Эдуарда","Погода в Волшебной стране","Три бегуньи на дорожке","Разные остатки от деления","Звёздочка в таблице","Остров с хитрецами","Суммы цифр соседних чисел","Карлсон и булочки"]};
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const officialSolutions = globalThis.KENGURU_GRADE_SOLUTION_STEPS ?? {};
  const nativeConditions = globalThis.KENGURU_GRADE_CONDITIONS ?? {};
  const nativeKeys = globalThis.KENGURU_GRADE_KEYS ?? {};
  const visualLessons = globalThis.KenguruVisualLessons ?? {};
  const editorialTitles = globalThis.KENGURU_GRADE_TITLES ?? {};

  function conditionScene(path, width, height, label) {
    return visual.svg(`<image href="${visual.escape(path)}" width="${width}" height="${height}"/>`,
      label, `0 0 ${width} ${height}`, 'legacy-scene').replace('<svg ', `<svg style="max-width:${width}px" `);
  }

  function answerDiagram(path, sourceWidth, sourceHeight) {
    const scale = Math.min(420 / sourceWidth, 300 / sourceHeight);
    const width = sourceWidth * scale;
    const height = sourceHeight * scale;
    const x = (420 - width) / 2;
    const drawing = visual.svg(`<image href="${visual.escape(path)}" x="${x}" y="8" width="${width}" height="${height}"/>`,
      'Рисунок к официальному ответу', `0 0 420 ${height + 16}`, 'worked-scene');
    return path.endsWith('.svg') ? drawing
      : drawing.replace('<svg ', `<svg style="max-width:${840 / scale}px;margin-inline:auto" `);
  }

  function officialSteps(stages) {
    return stages.map(({text, title}, index) => [
      index === stages.length - 1 ? 'Ответ' : `Шаг ${index + 1}`,
      title ?? (index === 0 ? 'Начинаем решение' : index === stages.length - 1 ? 'Проверяем ответ' : 'Продолжаем решение'),
      text,
    ]);
  }

  function createEdition(edition) {
    const {year, id, grades, label, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const answerLetters = [...(year < 2008 ? 'ABCDE' : 'АБВГД')];
    const groupSize = cards.length / 3;
    const lessons = [];
    const scenes = [];

    for (const [index, [width, height, letterKey]] of cards.entries()) {
      const number = index + 1;
      const padded = String(number).padStart(2, '0');
      const folder = `assets/grades-5-6/${year}`;
      const originalImage = `${folder}/task-${padded}.webp`;
      const description = `Условие задачи №${number}. Кенгуру ${year}, 5–6 классы.`;
      const custom = visualLessons[year]?.[number];
      const native = nativeConditions[year]?.[number];
      const solution = officialSolutions[year]?.[number];
      const official = solution?.steps;
      const question = custom?.question ?? solution?.question ?? native?.question ?? '';
      const choices = custom?.choices ?? solution?.choices ?? native?.choices ?? ['', '', '', '', ''];
      const paperEdition = !custom && !official?.length;
      const intro = ['Условие', 'Условие задачи', 'Выбери ответ и нажми «Далее».'];
      const officialKey = nativeKeys[year]?.[index];
      const [answerText, answerLetter, answerImage, answerWidth, answerHeight] = officialKey ?? [];
      const answer = solution?.answer ?? (officialKey && answerLetter ? answerLetters.indexOf(answerLetter) : letterKey);
      const answerStep = officialKey
        ? ['Ответ', 'Официальный ответ', answerLetter ? `Вариант ${answerLetter}. ${answerText}` : answerText]
        : ['Ответ', 'Проверяем ответ', 'Сравни свой выбор с официальным ответом.'];
      const steps = custom?.steps ?? [intro, ...(official?.length ? officialSteps(official) : [answerStep])];
      const figure = native?.image;
      const title = custom?.title ?? editorialTitles[year]?.[index] ?? `Задача ${number}`;

      lessons.push({
        number,
        title,
        short: custom?.short ?? title,
        skill: custom?.skill ?? '',
        answer,
        choices,
        choiceImages: custom ? custom.choiceImages : native?.choiceImages,
        question,
        ...(solution?.questionNote ? {questionNote: solution.questionNote} : {}),
        conditionImage: custom?.conditionImage ?? (!custom ? figure : undefined),
        conditionAlt: !custom ? native?.figureAlt : undefined,
        legacyOriginal: !custom || Boolean(custom.originalAtStart),
        hideIntroText: !custom,
        paperEdition,
        showCompletedStep: !paperEdition,
        officialValueKey: Boolean(officialKey),
        points: 3 + Math.floor(index / groupSize),
        originalImage,
        steps,
      });

      const initialScene = !question || custom?.originalAtStart
        ? conditionScene(originalImage, width, height, description)
        : figure && !custom ? conditionScene(figure, native.imageWidth, native.imageHeight, native.figureAlt ?? description) : '';
      const key = officialKey
        ? (answerImage ? answerDiagram(answerImage, answerWidth, answerHeight) : '')
        : visual.answerScene({letter: answerLetters[answer], value: choices[answer]});
      scenes.push((step, frame) => {
        if (custom && !(step === 0 && custom.originalAtStart)) return custom.scene(step, frame);
        if (step === 0) return initialScene;
        if (paperEdition) return key;
        // An empty stage is appropriate when this part of the proof has only a verbal argument.
        return visual.workedScene(official[step - 1], frame) || (step === steps.length - 1 ? key : '');
      });
    }

    return {year, id, grades, label, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes, paperEdition: true};
  }

  for (const edition of globalThis.KENGURU_GRADES_5_6 ?? []) {
    archive[edition.id] = createEdition(edition);
  }
})();

